import pandas as pd, json
d=pd.read_csv('data/measurements.csv')
d['brand']=d.brand.str.strip().replace({'7 for all Mankind':'7 for All Mankind'})
cols=['brand','style','menWomen','name','price','maxHeightFront','maxWidthFront','maxHeightBack','maxWidthBack']
data=d[cols].to_json(orient='records')
html=open('/dev/stdin').read() if False else None
tpl=r'''<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<title>Pocket gap: front and back pockets in men's and women's jeans</title>
<style>
:root{--m:#2f6db5;--w:#d2553f;--ink:#1d1d1f;--mute:#6b6b70;--rule:#e4e2dc}
*{box-sizing:border-box}
body{margin:0;background:#faf8f4;color:var(--ink);font:18px/1.6 Georgia,"Times New Roman",serif}
main{max-width:960px;margin:0 auto;padding:64px 32px 96px}
h1{font:700 48px/1.1 "Helvetica Neue",Arial,sans-serif;letter-spacing:-.02em;margin:0 0 16px}
h2{font:700 26px/1.2 "Helvetica Neue",Arial,sans-serif;margin:64px 0 8px}
.dek{font-size:21px;color:#3a3a3e;max-width:760px}
.meta{font:14px/1.5 "Helvetica Neue",Arial,sans-serif;color:var(--mute);margin-top:12px}
.m{color:var(--m);font-weight:700}.w{color:var(--w);font-weight:700}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:40px 0 8px}
.stat{background:#fff;border:1px solid var(--rule);padding:20px 22px;border-radius:6px}
.stat b{display:block;font:700 40px/1.1 "Helvetica Neue",Arial,sans-serif}
.stat span{font:14px/1.4 "Helvetica Neue",Arial,sans-serif;color:var(--mute)}
figure{margin:24px 0 0;background:#fff;border:1px solid var(--rule);border-radius:6px;padding:20px 24px}
figcaption{font:13px/1.5 "Helvetica Neue",Arial,sans-serif;color:var(--mute);margin-top:8px}
svg text{font-family:"Helvetica Neue",Arial,sans-serif}
.legend{font:14px "Helvetica Neue",Arial,sans-serif;margin-bottom:6px}
.legend i{display:inline-block;width:11px;height:11px;border-radius:50%;margin:0 6px 0 14px;vertical-align:-1px}
.legend i:first-child{margin-left:0}
#tip{position:fixed;pointer-events:none;background:#1d1d1f;color:#fff;font:13px/1.4 "Helvetica Neue",Arial,sans-serif;padding:6px 9px;border-radius:4px;opacity:0;transition:opacity .1s}
.notes{font:14px/1.6 "Helvetica Neue",Arial,sans-serif;color:var(--mute);border-top:1px solid var(--rule);margin-top:64px;padding-top:16px}
</style></head><body>
<main>
<h1>Women's jeans give you half a pocket</h1>
<p class="dek">I looked at front and back pocket measurements for 80 pairs of jeans, <span class="m">40 men's</span> and <span class="w">40 women's</span>, from 20 popular brands. Women's front pockets are much shallower than men's. Back pockets, which nobody uses for a phone, are about the same size for both.</p>
<p class="meta">All measurements are in centimetres. Front-pocket depth is the deepest point of the pocket bag, measured from the top of the waistband.</p>

<div class="stats">
 <div class="stat"><b><span class="w">14.3</span> vs <span class="m">23.1</span></b><span>average front pocket depth, women's vs men's</span></div>
 <div class="stat"><b>1 of 40</b><span>women's front pockets as deep as the shallowest men's one (20.0)</span></div>
 <div class="stat"><b>20 of 20</b><span>brands where the men's front pockets are deeper on average</span></div>
</div>

<h2>Front pockets: two groups that barely overlap</h2>
<p>Each dot is one pair of jeans. Men's front pockets run from 20.0 to 28.0 deep; women's run from 11.5 to 21.5. Only one women's pair, Abercrombie's Simone High Rise Slim at 21.5, reaches the shallowest men's pocket. On average women's front pockets are 14.3 deep against 23.1 for men's, and a little narrower too: 15.2 across the opening against 16.4.</p>
<figure><div class="legend"><i style="background:var(--m)"></i>Men's <i style="background:var(--w)"></i>Women's</div><svg id="strip" width="100%" viewBox="0 0 900 230"></svg>
<figcaption>Maximum front pocket depth, cm. The short vertical line marks each group's average. Hover a dot for the brand and model.</figcaption></figure>

<h2>The gap is in the front, not the back</h2>
<p>Back pockets are close in size: men's average 16.0 high and 13.7 wide, women's 15.1 high and 13.3 wide. The difference is concentrated in front, where it matters for carrying a phone or keys. In 29 of the 40 women's pairs the front pocket is actually shallower than the back pocket. That never happens in the men's jeans.</p>
<figure><div class="legend"><i style="background:var(--m)"></i>Men's <i style="background:var(--w)"></i>Women's</div><svg id="bars" width="100%" viewBox="0 0 900 250"></svg>
<figcaption>Average of each measurement across 40 men's and 40 women's jeans, cm.</figcaption></figure>

<h2>Every brand does it</h2>
<p>Each brand in the data sells two men's and two women's pairs. In all 20 brands the men's front pockets are deeper on average. The gap is smallest at Abercrombie (2.5) and largest at Levi's (13.4).</p>
<figure><div class="legend"><i style="background:var(--m)"></i>Men's average <i style="background:var(--w)"></i>Women's average</div><svg id="brands" width="100%" viewBox="0 0 900 640"></svg>
<figcaption>Average maximum front pocket depth per brand, cm. Brands sorted by size of the gap, smallest first. Gap shown on the right.</figcaption></figure>

<h2>Neither cut nor price fixes it</h2>
<p>For women, cut makes little difference: average front pocket depth is 14.3 for skinny, 14.4 for straight and 14.2 for boot-cut jeans. Paying more does not help either. The correlation between price and front-pocket depth is −0.15 for women's jeans and −0.26 for men's, so pricier jeans, if anything, have slightly shallower pockets.</p>
<figure><div class="legend"><i style="background:var(--m)"></i>Men's <i style="background:var(--w)"></i>Women's</div><svg id="price" width="100%" viewBox="0 0 900 340"></svg>
<figcaption>Price (US$) against maximum front pocket depth (cm), one dot per pair of jeans.</figcaption></figure>

<p class="notes">Data: front and back pocket measurements of 80 pairs of jeans (two men's and two women's styles from each of 20 brands), with list price, cut and fabric. Brand spellings were made consistent ("7 for all Mankind" merged with "7 for All Mankind"). With only four pairs per brand and one size measured per style, brand averages are rough indications rather than precise figures.</p>
</main>
<div id="tip"></div>
<script>
const D=__DATA__;
const NS="http://www.w3.org/2000/svg",C={men:"#2f6db5",women:"#d2553f"};
function el(p,t,a,txt){const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);if(txt!=null)e.textContent=txt;p.appendChild(e);return e}
const tip=document.getElementById("tip");
function hover(e,html){e.addEventListener("mousemove",ev=>{tip.innerHTML=html;tip.style.opacity=1;tip.style.left=ev.clientX+12+"px";tip.style.top=ev.clientY+12+"px"});e.addEventListener("mouseleave",()=>tip.style.opacity=0)}
const mean=a=>a.reduce((s,x)=>s+x,0)/a.length;
const G=["men","women"],lab={men:"Men's",women:"Women's"};

// strip plot
(function(){const s=document.getElementById("strip"),L=110,R=880,x=v=>L+(v-10)/(30-10)*(R-L);
 for(let v=10;v<=30;v+=2){el(s,"line",{x1:x(v),x2:x(v),y1:20,y2:190,stroke:"#eee"});el(s,"text",{x:x(v),y:212,"text-anchor":"middle","font-size":13,fill:"#6b6b70"},v)}
 el(s,"text",{x:R,y:228,"text-anchor":"end","font-size":12,fill:"#6b6b70"},"cm deep");
 G.forEach((g,i)=>{const cy=i?140:65,rows=D.filter(d=>d.menWomen==g).sort((a,b)=>a.maxHeightFront-b.maxHeightFront),cnt={};
  el(s,"text",{x:0,y:cy+5,"font-size":15,"font-weight":700,fill:C[g]},lab[g]);
  rows.forEach(d=>{const k=d.maxHeightFront,n=cnt[k]=(cnt[k]||0)+1,off=(n%2?1:-1)*Math.floor(n/2)*9;
   const c=el(s,"circle",{cx:x(k),cy:cy+off,r:5,fill:C[g],"fill-opacity":.65,stroke:"#fff"});hover(c,`<b>${d.brand}</b> ${d.name}<br>${k} cm deep`)});
  const m=mean(rows.map(d=>d.maxHeightFront));el(s,"line",{x1:x(m),x2:x(m),y1:cy-34,y2:cy+34,stroke:"#1d1d1f","stroke-width":2});
  el(s,"text",{x:x(m),y:cy-38,"text-anchor":"middle","font-size":13,"font-weight":700},"avg "+m.toFixed(1))});
})();

// bars
(function(){const s=document.getElementById("bars"),M=[["maxHeightFront","Front pocket depth"],["maxWidthFront","Front pocket width"],["maxHeightBack","Back pocket height"],["maxWidthBack","Back pocket width"]],L=200,R=820,x=v=>L+v/25*(R-L);
 M.forEach(([k,t],i)=>{const y=10+i*58;el(s,"text",{x:L-12,y:y+24,"text-anchor":"end","font-size":14},t);
  G.forEach((g,j)=>{const v=mean(D.filter(d=>d.menWomen==g).map(d=>d[k]));el(s,"rect",{x:L,y:y+j*20,width:x(v)-L,height:17,fill:C[g]});el(s,"text",{x:x(v)+6,y:y+j*20+13,"font-size":13,fill:C[g],"font-weight":700},v.toFixed(1))})});
 for(let v=0;v<=25;v+=5){el(s,"text",{x:x(v),y:246,"text-anchor":"middle","font-size":12,fill:"#6b6b70"},v)}
})();

// brand dumbbells
(function(){const s=document.getElementById("brands"),by={};D.forEach(d=>{(by[d.brand]=by[d.brand]||{men:[],women:[]})[d.menWomen].push(d.maxHeightFront)});
 const B=Object.entries(by).map(([b,v])=>({b,m:mean(v.men),w:mean(v.women)})).sort((a,c)=>(a.m-a.w)-(c.m-c.w)||a.b.localeCompare(c.b));
 const L=170,R=800,x=v=>L+(v-10)/(30-10)*(R-L);
 for(let v=10;v<=30;v+=5){el(s,"line",{x1:x(v),x2:x(v),y1:0,y2:610,stroke:"#eee"});el(s,"text",{x:x(v),y:630,"text-anchor":"middle","font-size":12,fill:"#6b6b70"},v)}
 el(s,"text",{x:870,y:12,"text-anchor":"end","font-size":12,fill:"#6b6b70"},"gap");
 B.forEach((r,i)=>{const y=30+i*29.5;el(s,"text",{x:L-14,y:y+5,"text-anchor":"end","font-size":14},r.b);
  el(s,"line",{x1:x(r.w),x2:x(r.m),y1:y,y2:y,stroke:"#c9c6bf","stroke-width":3});
  hover(el(s,"circle",{cx:x(r.w),cy:y,r:7,fill:C.women}),`${r.b} women's: ${r.w.toFixed(2)} cm`);
  hover(el(s,"circle",{cx:x(r.m),cy:y,r:7,fill:C.men}),`${r.b} men's: ${r.m.toFixed(2)} cm`);
  el(s,"text",{x:870,y:y+5,"text-anchor":"end","font-size":13,"font-weight":700},(r.m-r.w).toFixed(2).replace(/\.?0+$/,""))});
})();

