(function(){const s=document.getElementById("price"),L=60,R=880,T=10,Bt=290,x=v=>L+v/260*(R-L),y=v=>Bt-(v-10)/(30-10)*(Bt-T);
 for(let v=10;v<=30;v+=5){el(s,"line",{x1:L,x2:R,y1:y(v),y2:y(v),stroke:"#eee"});el(s,"text",{x:L-8,y:y(v)+4,"text-anchor":"end","font-size":12,fill:"#6b6b70"},v)}
 for(let v=0;v<=250;v+=50){el(s,"text",{x:x(v),y:Bt+20,"text-anchor":"middle","font-size":12,fill:"#6b6b70"},"$"+v)}
 el(s,"text",{x:R,y:Bt+40,"text-anchor":"end","font-size":12,fill:"#6b6b70"},"price");
 el(s,"text",{x:L,y:T+4,"font-size":12,fill:"#6b6b70",dx:6},"front pocket depth, cm");
 D.forEach(d=>hover(el(s,"circle",{cx:x(d.price),cy:y(d.maxHeightFront),r:5.5,fill:C[d.menWomen],"fill-opacity":.65,stroke:"#fff"}),`<b>${d.brand}</b> ${d.name}<br>$${d.price} · ${d.maxHeightFront} cm deep`));
})();
</script></body></html>'''
open('index.html','w').write(tpl.replace('__DATA__',data))
